<div class="toolbar"><p class="muted">Del diagnóstico al cuidado, con cada procedimiento registrado.</p><a class="button" href="#new-plan"><?= icon('plus',18) ?> Nuevo plan</a></div>
<section class="panel"><div class="panel-heading"><h2>Planes de tratamiento</h2><span class="muted"><?= count($plans) ?> planes</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Plan / paciente</th><th>Responsable</th><th>Estado</th><th>Presupuesto</th><th>Pagado</th><th>Saldo</th></tr></thead><tbody><?php foreach($plans as $p): ?><tr><td><strong>#<?= (int)$p['id'] ?> · <?= e($p['name']) ?></strong><small><?= e($p['patient']) ?></small></td><td><?= e($p['dentist']) ?></td><td><?= badge($p['status']) ?></td><td><?= money($p['total']) ?></td><td><?= money($p['paid']) ?></td><td><strong><?= money((float)$p['total']-(float)$p['paid']) ?></strong></td></tr><?php endforeach; ?><?php if(!$plans): ?><tr><td colspan="6" class="empty">Crea el primer plan de tratamiento.</td></tr><?php endif; ?></tbody></table></div></section>
<details class="panel form-panel" id="new-plan"><summary>Crear un plan de tratamiento</summary><form method="post" class="form-grid" data-loading><?= csrf_field() ?><?php field('name','Nombre del plan'); choose('patient_id','Paciente',patient_options($patients)); choose('dentist_id','Profesional responsable',array_column($dentists,'name','id')); choose('treatment_id','Primer procedimiento',array_column($catalog,'name','id')); field('tooth_fdi','Pieza FDI (opcional)','','number',false); area('notes','Observaciones'); ?><p class="full muted">El procedimiento se registra como planificado. Su precio se toma del catálogo y queda guardado en el presupuesto.</p><button class="button">Crear plan</button></form></details>
<details class="panel form-panel"><summary>Añadir un procedimiento a un plan</summary><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="item"><?php choose('plan_id','Plan',array_combine(array_column($plans,'id'),array_map(fn($p)=>'#'.$p['id'].' · '.$p['patient'].' · '.$p['name'],$plans)) ?: []); choose('treatment_id','Procedimiento',array_column($catalog,'name','id')); field('tooth_fdi','Pieza FDI (opcional)','','number',false); area('notes','Observaciones'); ?><button class="button">Añadir procedimiento</button></form></details>
<section class="panel"><div class="panel-heading"><h2>Procedimientos y evolución</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Procedimiento / plan</th><th>Pieza</th><th>Precio</th><th>Facturación</th><th>Clínico</th><th>Actualizar facturación</th><th>Detalle</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?= e($i['treatment']) ?></strong><small><?= e($i['patient']) ?> · <?= e($i['plan']) ?></small></td><td><?= e($i['tooth_fdi'] ?: '—') ?></td><td><?= money($i['price']) ?></td><td><?= badge($i['status']) ?><?php if($i['completed_at']): ?><small><?= local_date($i['completed_at']) ?></small><?php endif; ?></td><td><span class="badge <?= e($i['clinical_status']) ?>"><?= e(label($i['clinical_status'])) ?></span></td><td><form class="inline-form" method="post" data-confirm="Se actualizará el estado del procedimiento. Verifica que corresponda a la atención realizada."><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$i['id'] ?>"><select name="status" aria-label="Estado del procedimiento"><?php foreach(['planned','in_progress','completed','cancelled'] as $s): ?><option value="<?= $s ?>"<?= selected($i['status'],$s) ?>><?= e(label($s)) ?></option><?php endforeach; ?></select><input name="notes" aria-label="Evolución u observaciones" placeholder="Evolución / observaciones" value="<?= e($i['notes']) ?>" maxlength="2000"><button class="button small secondary">Guardar</button></form></td><td><a class="table-link" href="<?= e(url('/admin/treatment?id='.$i['id'])) ?>">Abrir <?= icon('arrow',14) ?></a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7" class="empty">Los procedimientos del plan aparecerán aquí.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Catálogo de tratamientos</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Código</th><th>Tratamiento</th><th>Precio</th><th>Duración</th><th>Editar</th></tr></thead><tbody><?php foreach($catalog as $t): ?><tr><td><?= e($t['code']) ?></td><td><?= e($t['name']) ?></td><td><?= money($t['price']) ?></td><td><?= (int)$t['duration_minutes'] ?> min</td><td><details><summary>Editar tratamiento</summary><form method="post" class="stack"><?= csrf_field() ?><input type="hidden" name="action" value="catalog"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><?php field('code','Código',$t['code']); field('name','Nombre',$t['name']); field('price','Precio',$t['price'],'number',true,'step="0.01" min="0"'); field('duration_minutes','Minutos',$t['duration_minutes'],'number',true,'min="15" max="240"'); area('description','Descripción',$t['description']); ?><button class="button small">Guardar</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></section>
<details class="panel form-panel"><summary>Agregar al catálogo</summary><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="catalog"><?php field('code','Código'); field('name','Nombre'); field('price','Precio','','number',true,'min="0" step="0.01"'); field('duration_minutes','Duración en minutos','30','number',true,'min="15" max="240"'); area('description','Descripción'); ?><button class="button">Crear tratamiento</button></form></details>
